(function(){
'use strict';
const lang=(document.documentElement.lang||'en').toLowerCase();
const reduceMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const TXT={
 en:{limit:'Limit reached',qr:'QR capacity reached'},fr:{limit:'Limite atteinte',qr:'Capacité QR atteinte'},es:{limit:'Límite alcanzado',qr:'Capacidad QR alcanzada'},'pt-br':{limit:'Limite atingido',qr:'Capacidade do QR atingida'},ar:{limit:'تم بلوغ الحد',qr:'تم بلوغ سعة QR'}
}[lang]||{limit:'Limit reached',qr:'QR capacity reached'};
const enc=new TextEncoder();
const safeDefaults={name:80,email:254,subject:160,message:1000};
function countFor(el){return el.name==='ssid'?enc.encode(el.value||'').length:Array.from(el.value||'').length;}
function maxFor(el){if(el.name==='ssid')return 32;return el.maxLength>0?el.maxLength:0;}
function ensureMax(el){if(el.maxLength>0)return;const m=safeDefaults[el.name];if(m)el.maxLength=m;}
function counter(el){const field=el.closest('.field');if(!field)return null;let c=field.querySelector(':scope > .char-counter');if(!c){c=document.createElement('span');c.className='char-counter';c.setAttribute('aria-live','polite');const fb=field.querySelector(':scope > .field-feedback');fb?field.insertBefore(c,fb):field.appendChild(c);}return c;}
function paintCounter(el,capacity=false){ensureMax(el);const max=maxFor(el);if(!max)return;const c=counter(el);if(!c)return;const n=countFor(el),ratio=max?Math.min(1,n/max):0;c.classList.remove('is-green','is-yellow','is-red','is-max','is-capacity');if(n===0)c.classList.add('is-green');else if(ratio<.7)c.classList.add('is-green');else if(ratio<.9)c.classList.add('is-yellow');else c.classList.add('is-red');if(n>=max){c.classList.add('is-max');c.title=TXT.limit;}else c.title='';if(capacity){c.classList.add('is-red','is-capacity');c.title=TXT.qr;}c.textContent=`${n} / ${max}${capacity?' · '+TXT.qr:''}`;}
function tracked(el){if(!(el instanceof HTMLInputElement||el instanceof HTMLTextAreaElement))return false;if(!el.closest('[data-qr-form],[data-styled-form],[data-contact-form]'))return false;if(['file','color','range','radio','checkbox','number','datetime-local','hidden'].includes(el.type))return false;ensureMax(el);return maxFor(el)>0;}
function allTracked(){return [...document.querySelectorAll('[data-qr-form] input,[data-qr-form] textarea,[data-styled-form] input,[data-styled-form] textarea,[data-contact-form] input,[data-contact-form] textarea')].filter(tracked);}
function storeAccepted(el){el.dataset.lastAccepted=el.value||'';}
function capacityCheck(el){const form=el.closest('[data-qr-form],[data-styled-form]');if(!form)return false;const rt=window.FastooleeQRRuntime;if(!rt||rt.form!==form||typeof rt.canEncodeCurrent!=='function')return false;const result=rt.canEncodeCurrent();if(result&&result.reason==='capacity'){el.value=el.dataset.lastAccepted??'';paintCounter(el,true);form.classList.add('qr-capacity-hit');setTimeout(()=>form.classList.remove('qr-capacity-hit'),550);return true;}return false;}
allTracked().forEach(el=>{storeAccepted(el);paintCounter(el);});
document.addEventListener('beforeinput',e=>{const el=e.target;if(!tracked(el))return;el.dataset.lastAccepted=el.value||'';},true);
document.addEventListener('input',e=>{const el=e.target;if(!tracked(el))return;if(el.name==='ssid'&&enc.encode(el.value||'').length>32){el.value=el.dataset.lastAccepted||'';paintCounter(el);return;}if(capacityCheck(el))return;storeAccepted(el);paintCounter(el,false);},true);
document.addEventListener('change',e=>{const el=e.target;if(tracked(el)){storeAccepted(el);paintCounter(el,false);}},true);

// Smooth FAQ accordion with explicit open/close animation.
document.querySelectorAll('.faq details').forEach(details=>{
 const summary=details.querySelector(':scope > summary');if(!summary)return;
 const nodes=[...details.children].filter(n=>n!==summary);if(!nodes.length)return;
 const wrap=document.createElement('div');wrap.className='faq-answer';const inner=document.createElement('div');inner.className='faq-answer-inner';nodes.forEach(n=>inner.appendChild(n));wrap.appendChild(inner);details.appendChild(wrap);
 summary.setAttribute('aria-expanded',details.open?'true':'false');
 wrap.style.height=details.open?'auto':'0px';wrap.style.opacity=details.open?'1':'0';wrap.setAttribute('aria-hidden',details.open?'false':'true');
 let busy=false;
 summary.addEventListener('click',e=>{e.preventDefault();if(busy)return;const opening=!details.open;
   if(reduceMotion){details.open=opening;summary.setAttribute('aria-expanded',opening?'true':'false');wrap.setAttribute('aria-hidden',opening?'false':'true');wrap.style.height=opening?'auto':'0px';wrap.style.opacity=opening?'1':'0';return;}
   busy=true;
   if(opening){details.open=true;summary.setAttribute('aria-expanded','true');wrap.setAttribute('aria-hidden','false');wrap.style.height='0px';wrap.style.opacity='0';requestAnimationFrame(()=>{wrap.style.height=inner.scrollHeight+'px';wrap.style.opacity='1';});}
   else{summary.setAttribute('aria-expanded','false');wrap.style.height=inner.scrollHeight+'px';wrap.style.opacity='1';requestAnimationFrame(()=>{wrap.style.height='0px';wrap.style.opacity='0';});}
   const done=()=>{wrap.removeEventListener('transitionend',done);if(opening){wrap.style.height='auto';}else{details.open=false;wrap.setAttribute('aria-hidden','true');}busy=false;};wrap.addEventListener('transitionend',done);setTimeout(()=>{if(busy)done();},480);
 });
});
})();
